observation.command:
cd /tmp/logic-extract && for f in io/swcode/urbo/build/logic/CommonConventionsPlugin.class io/swcode/urbo/build/logic/Java_artifact_gradle*.class io/swcode/urbo/build/logic/Artifact_gradle*.class; do
echo "=== $f ===";
node -e '
const fs=require("fs");
try{
const data=fs.readFileSync(process.argv[1]);
let out="";
for(let i=0;i<data.length;i++){const c=data[i]; if(c>=32&&c<127) out+=String.fromCharCode(c); else out+="\n";}
console.log(out.split("\n").filter(s=>/github|\.io|amazonaws|amazon|\.org|\.com|url|http/i.test(s)).slice(0,20).join("\n"));
}catch(e){}
' "$f";
done 2>&1 | head -60
